#include<cstdio>
#include<stack>
#include<tuple>
using namespace std;

int n, s;
int memo[1024][1000];

int main() {
    while (scanf("%d%d", &n, &s) == 2) {
        for (int i = 0; i < 1024; i++) 
            for (int j = 0; j < 1000; j++) 
                memo[i][j] = -1;

        if (n > 10 || s >= 1000) {
            puts("0");
            continue;
        }

        stack<tuple<int, int, int>> stk;
        stk.push({0, 0, 0}); // (stat, sum, dep)
        int cnt = 0;

        while (!stk.empty()) {
            auto [stat, sum, dep] = stk.top();
            stk.pop();

            if (dep == n) {
                if (s == sum) cnt++;
                continue; // Check if we reached the depth first
            }
            if (sum > s) continue; // Early termination if the sum exceeds target

            for (int i = 0; i < 10; i++) {
                if (!(stat & (1 << i))) {
                    stk.push({stat | (1 << i), sum + i * (n - dep), dep + 1});
                }
            }
        }
        printf("%d\n", cnt);
    }
    return 0;
}

